pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 attempt) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= address(this).balance);
        vm.assume(attempt >= 1 && attempt <= 5);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

        bool firstOk;
        try c.withdrawAll() { firstOk = true; } catch { firstOk = false; }

        bool secondOk;
        vm.prank(actor);
        try c.withdrawAll() { secondOk = true; } catch { secondOk = false; }

        uint256 balanceAfter = address(c).balance;

        // Property: After a successful first withdrawal, the second withdrawal must fail
        // or not reduce balance further; the bug allows a second withdrawal draining more.
        if (firstOk) {
            assertTrue(!secondOk || balanceAfter == balanceBefore - depositAmount);
        } else {
            assertTrue(true);
        }
    }
}

