pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 creditAmount, address recipient) public {
        // Restrict amount to non-zero so that withdrawAll tries to send ether
        vm.assume(creditAmount > 0);
        // Use a fresh address that will reject ether (no fallback/receive)
        // The fuzzer will supply any address, many of which are EOAs that accept ether,
        // but the property must still hold for them; we want the bug to appear when ether transfer fails.
        // We deploy a minimal contract that reverts on receiving ether to act as the recipient.
        // However, we can only interact with c; we cannot deploy additional contracts in the test.
        // Instead, we set up the scenario: give credit to the fuzzed recipient, then prank as that recipient and attempt withdrawal.
        // For EOAs, ether transfer succeeds, but the bug still manifests as a state difference when transfer fails.
        // We must ensure the test can trigger the failed transfer; using a contract that reverts is the standard way.
        // Since the spec says "keep it WIDE" and we cannot deploy helper contracts, we accept that for EOAs the withdrawal succeeds.
        // The fuzzer will also generate contract addresses; we rely on the fuzzer to find one that causes failure.
        // We just record the credit before and after and assert it remains unchanged when withdrawal reverts.

        // Fund the contract and give credit to recipient
        vm.deal(address(this), creditAmount);
        vm.prank(address(this));
        c.deposit{value: creditAmount}();

        // Record initial credit
        uint256 creditBefore = c.credit(recipient);

        // Attempt withdrawal as recipient
        vm.prank(recipient);
        try c.withdrawAll() {
            // If it didn't revert, the transfer succeeded; we check that credit is zeroed.
            // This is allowed by the reference; no violation.
            assertTrue(c.credit(recipient) == 0);
        } catch {
            // If it reverted, the reference guarantees credit is unchanged.
            assertTrue(c.credit(recipient) == creditBefore);
        }
    }
}

