pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint8 attackDepth) public {
        // Keep depositAmount within reasonable bounds; attackDepth determines number of reentrant calls in the attack contract
        vm.assume(depositAmount > 0 && depositAmount <= address(this).balance / 2);
        vm.assume(attackDepth > 0 && attackDepth <= 10);

        // Deploy a reentrant attacker and fund it
        Attacker attacker = new Attacker(c, attackDepth);
        vm.deal(address(attacker), depositAmount);

        // Attacker deposits
        attacker.deposit{value: depositAmount}();

        // Record total deposited amount (attacker's deposit only)
        uint256 totalDeposited = depositAmount;

        // Attacker triggers the withdrawAll from within, which attempts reentrancy
        attacker.attack();

        // Read the final balance of C and attacker's credit
        uint256 contractBalance = address(c).balance;
        uint256 attackerCredit = c.credit(address(attacker));

        // The invariant: sum of contract balance and attacker's credit must equal the total deposited amount
        // In the reference version, this holds because the reentrancy is blocked.
        // In the buggy version, reentrancy allows multiple balance deductions for the same credit,
        // making contractBalance + attackerCredit < totalDeposited.
        assertTrue(contractBalance + attackerCredit == totalDeposited);
    }
}

contract Attacker {
    C public target;
    uint8 public depth;
    uint8 public maxDepth;

    constructor(C _target, uint8 _maxDepth) {
        target = _target;
        maxDepth = _maxDepth;
    }

    function deposit() external payable {
        target.deposit{value: msg.value}();
    }

    function attack() external {
        depth = 0;
        target.withdrawAll();
    }

    receive() external payable {
        if (depth < maxDepth) {
            depth++;
            target.withdrawAll();
        }
    }
}

