pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, address actor, address attacker) public {
        vm.assume(depositAmount > 0 && depositAmount <= 100 ether);
        vm.assume(actor != address(0) && attacker != address(0) && actor != attacker);
        vm.assume(actor != address(c) && attacker != address(c));

        // Setup: actor deposits and attacker deposits the same amount
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        vm.deal(attacker, depositAmount);
        vm.prank(attacker);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;
        uint256 attackerCreditBefore = c.credit(attacker);

        // Attacker calls withdrawAll (which may trigger reentrancy in the buggy version)
        vm.prank(attacker);
        c.withdrawAll();

        uint256 balanceAfter = address(c).balance;
        uint256 attackerCreditAfter = c.credit(attacker);
        uint256 actorCreditAfter = c.credit(actor);

        // General rule: After withdrawal, the contract balance should never be less than
        // the sum of all remaining credits. Since actor never withdrew, the balance
        // must at least equal actor's credit. The bug allows reentrant withdrawal
        // to steal actor's funds, making balance < actor's credit.
        assertTrue(balanceAfter >= actorCreditAfter);
    }
}

